        private skryjDleMeny(): void
        {
            var that = this;

            that.element.findForms("pokInformace").findFormRows("field:c_pri_hl,field:c_vyd_hl,field:c_zust_hl,field:c_pri_den,field:c_vyd_den,field:c_zust_den,field:c_pocatek,field:c_zustatek").toggle(that.model.mena != 0);
            
        }


        private loadData(): JQueryPromise<void>{

            var that = this;
            var def = $.Deferred();
            that.beginOperation("Načítání informací o knize");

            that.isl.PokKniha.read({
                ixp_den: this.ixpDen,
                fragments: ["POKSDEN", "Permissions"]
            })
                .getData()
                .done(function (data) {

                    that.zkrMena = data.mena_zkr;
                    that.model = data;
                    that.editovatelnost = that.model.Permissions!.CanEdit.value;
                    def.resolve();
                }).fail(function (xhr, typ, obj) {
                    def.reject();
                })
                .always(function () {
                    that.endOperation();
                });

            return def.promise();
        }

